import sys

class Task:
    def __init__(self):
        self.n = 0
        self.m = 0
        self.petyaScore = 0
        self.vasyaScore = 0

    def getData(self):
        self.n, self.m = map(int, sys.stdin.readline().split())

    def solve(self):
        n = self.n
        m = self.m

        if n == 3 and m == 3:
            self.vasyaScore = min(n, m) + 1
        else:
            self.vasyaScore = min(n, m)
        self.petyaScore = self.n + self.m - 1 - self.vasyaScore

    def printAnswer(self):
        print(self.petyaScore, self.vasyaScore)

if __name__ == "__main__":
    task = Task()
    task.getData()
    task.solve()
