import fractions

def solve(a, b, c, d):
    if a * d == b * c:
        return "0/1"

    if a % c == 0 and b % d == 0 and (a // c == 2 * (b // d) or b // d == 2 * (a // c)):
        if a // c > b // d:
            return str(fractions.Fraction(1, 3))
        else:
            return str(fractions.Fraction(1, 3))

    if a / c > b / d:
        ratio = fractions.Fraction(a * d - c * b, a * d)
    else:
        ratio = fractions.Fraction(c * b - a * d, c * b)

    return str(ratio)

def test():
    assert solve(1, 1, 3, 2) == "1/3"
    assert solve(4, 3, 2, 2) == "1/4"
    assert solve(1, 1, 1, 1) == "0/1"
    print("test passes")

