def find(start, end, v):
    mid = int((start + end) / 2)
    if start == end:
        return start
    if end - start == 1:
        if a[end] < v:
            return end
        else:
            return start
    if a[mid] == v:
        return mid
    if a[mid] > v:
        return find(start, mid, v)
    else:
        return find(mid, end, v)

