from functools import lru_cache
import sys
sys.setrecursionlimit(100000000)

@lru_cache(maxsize=None)
def rec(twos, ones):
    global mod
    if twos == 0 and ones == 0:
        return 1
    if twos == 1 and ones == 0:
        return 0
    else:
        count = 0
        if (ones >= 2):
            a = ones*(ones-1)//2
            b = rec(twos, ones-2)
            count += (a*b) % mod
        if (ones >= 1 and twos >= 1):
            a = ones*twos
            b = rec(twos-1, ones)
            count += (a*b) % mod
        if (twos >= 2):
            a = twos*(twos-1)//2
            if twos == 2 and ones % 2 == 1:
                b = rec(twos-2, ones+1)
            else:
                b = rec(twos-2, ones+2)
            count += (a*b) % mod
        return count % mod

